#pragma once
#include "updater.hpp"
namespace snuw {
inline fs::path executableFile(){wchar_t name[32768];DWORD length=GetModuleFileNameW(nullptr,name,32768);if(!length||length>=32768)throw std::runtime_error("실행 파일 경로 오류");return fs::path(std::wstring(name,length));}
inline fs::path localBuildReadyFile(const fs::path& root,const fs::path& target){return updatePath(root,fs::path(L".updates/local")/(target.filename().wstring()+L".ready.json"));}
inline fs::path localBuildCandidate(const fs::path& root,const json& build){auto hash=str(build,"sha256");if(!std::regex_match(hash,std::regex("[a-f0-9]{64}")))throw std::runtime_error("로컬 빌드 해시 오류");return updatePath(root,fs::path(L".updates/local")/(wide(hash)+L".exe"));}
inline fs::path localBuildTarget(const fs::path& root,const json& build){auto name=str(build,"target");if(name!="SNUWCANVAS.exe"&&name!="SNUWCANVAS-custom-server.exe")throw std::runtime_error("로컬 빌드 대상 오류");return updatePath(root,wide(name));}
inline fs::path localBuildAppliedFile(const fs::path& root){return updatePath(root,fs::path(L".updates/local")/L"applied.json");}
inline long long localBuildAppliedAt(const fs::path& root){try{return readJson(localBuildAppliedFile(root)).value("built_at",0LL);}catch(...){return 0;}}
inline void localBuildMarkApplied(const fs::path& root,const json& build){try{auto at=build.value("built_at",0LL);if(at>localBuildAppliedAt(root))atomicWrite(localBuildAppliedFile(root),json{{"built_at",at}}.dump());}catch(...){}}
/** Descriptors on disk are signed envelopes; only the verified payload is ever trusted. Fails closed without an embedded key. */
inline json localBuildOpen(const json& envelope){std::string key=LOCAL_BUILD_PUBLIC_KEY_HEX;if(key.empty())throw std::runtime_error("이 앱에는 로컬 빌드 서명 키가 없어 로컬 업데이트를 적용하지 않습니다.");auto payload=from64(str(envelope,"payload")),signature=from64(str(envelope,"signature"));if(payload.size()>8192||signature.size()<384||signature.size()>1024)throw std::runtime_error("로컬 빌드 서명 크기 오류");try{verifySignature(payload,signature,key);}catch(const std::exception&){throw std::runtime_error("로컬 빌드 서명 검증 실패 · 적용하지 않았습니다.");}return json::parse(payload);}
inline void validateLocalBuild(const fs::path& root,const json& build,bool allowOlder=true){if(build.value("schema",0)!=2||build.value("release_epoch",0)!=2||str(build,"version").empty()||!std::regex_match(str(build,"build_id"),std::regex("[a-f0-9]{32}"))||build.value("built_at",0LL)<=0)throw std::runtime_error("로컬 빌드 정보 오류");if(!allowOlder&&build.value("built_at",0LL)<localBuildAppliedAt(root))throw std::runtime_error("이미 적용한 빌드보다 오래된 빌드입니다. 전체 설정의 새 빌드 적용으로 직접 적용하세요.");localBuildTarget(root,build);validateCandidate(localBuildCandidate(root,build),build);}
inline fs::path localBuildStatusFile(const fs::path& root,const json& build){return updatePath(root,fs::path(L".updates/local")/(wide(str(build,"target"))+L".status.json"));}
inline void localBuildStatus(const fs::path& root,const json& build,const std::string& state,const std::string& error=""){atomicWrite(localBuildStatusFile(root,build),json{{"sha256",str(build,"sha256")},{"build_id",str(build,"build_id","")},{"built_at",build.value("built_at",0LL)},{"target",str(build,"target")},{"state",state},{"helper_pid",build.value("helper_pid",GetCurrentProcessId())},{"error",error}}.dump(2));}
inline void localBuildHealthy(const fs::path& root){auto target=executableFile();auto file=updatePath(root,fs::path(L".updates/local")/(target.filename().wstring()+L".status.json"));if(!fs::exists(file))return;auto status=readJson(file);auto state=str(status,"state");if((state=="awaiting_health"||state=="health_unconfirmed")&&str(status,"sha256")==fileSha256(target))localBuildStatus(root,status,"healthy");localBuildMarkApplied(root,status);}
inline void installLocalBuild(const fs::path& root,const json& build,bool* replaced=nullptr){
 validateLocalBuild(root,build);auto target=localBuildTarget(root,build),candidate=localBuildCandidate(root,build);if(fileSha256(target)==str(build,"sha256")){if(replaced)*replaced=true;return;}
 auto old=fileSha256(target);auto backup=updatePath(root,fs::path(L".updates/local/backups")/(wide(old)+L".exe"));fs::create_directories(backup.parent_path());if(fs::exists(backup)&&fileSha256(backup)!=old)throw std::runtime_error("이전 빌드 백업 검증 실패");
 if(!ReplaceFileW(target.c_str(),candidate.c_str(),fs::exists(backup)?nullptr:backup.c_str(),REPLACEFILE_IGNORE_MERGE_ERRORS,nullptr,nullptr))throw std::runtime_error("새 빌드 적용 실패 · 이전 파일을 보존했습니다.");
 if(replaced)*replaced=true;
 if(fileSha256(target)!=str(build,"sha256"))throw std::runtime_error("적용 후 빌드 검증 실패");
}
inline void startLocalBuildHelper(const fs::path& root,const json& build){validateLocalBuild(root,build);auto candidate=localBuildCandidate(root,build),helper=updatePath(root,fs::path(L".updates/local/helpers")/(wide(str(build,"sha256"))+L".exe"));fs::create_directories(helper.parent_path());if(!fs::exists(helper))fs::copy_file(candidate,helper);validateCandidate(helper,build);auto process=updateProcess(helper,L"--apply-local-build "+updateQuote(root.wstring())+L" "+std::to_wstring(GetCurrentProcessId())+L" "+wide(str(build,"sha256"))+L" "+updateQuote(wide(str(build,"target"))));CloseHandle(process.hThread);CloseHandle(process.hProcess);}
inline std::string localBuildState(const fs::path& file){for(int attempt=0;attempt<5;attempt++){try{return str(readJson(file),"state");}catch(...){Sleep(40);}}return "";}
inline void localBuildLog(const fs::path& root,const std::string& line){try{std::ofstream out(updatePath(root,L".updates/local/apply.log"),std::ios::app);out<<line<<"\n";}catch(...){}}
inline int applyLocalBuild(const fs::path& root,DWORD parent,const std::string& expected,const std::string& name){json build;fs::path target;bool installed=false,parentStopped=false;std::string oldHash;HANDLE childProcess=nullptr;try{
 if(name!="SNUWCANVAS.exe"&&name!="SNUWCANVAS-custom-server.exe")return 1;auto lockPath=updatePath(root,fs::path(L".updates/local")/(wide(name)+L".apply.lock"));HANDLE lock=CreateFileW(lockPath.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_ALWAYS,FILE_ATTRIBUTE_HIDDEN,nullptr);if(lock==INVALID_HANDLE_VALUE)return 2;struct ApplyLock{HANDLE value;~ApplyLock(){CloseHandle(value);}} guard{lock};
 if(!std::regex_match(expected,std::regex("[a-f0-9]{64}")))throw std::runtime_error("빌드 식별값 오류");build=localBuildOpen(readJson(updatePath(root,fs::path(L".updates/local")/(wide(expected)+L".json"))));if(str(build,"sha256")!=expected||str(build,"target")!=name)throw std::runtime_error("빌드 정보가 일치하지 않습니다.");target=localBuildTarget(root,build);validateLocalBuild(root,build);
 HANDLE owner=parent?OpenProcess(SYNCHRONIZE,FALSE,parent):nullptr;if(parent&&!owner&&GetLastError()!=ERROR_INVALID_PARAMETER)throw std::runtime_error("이전 앱 종료를 확인할 수 없습니다.");if(owner){auto result=WaitForSingleObject(owner,120000);CloseHandle(owner);if(result!=WAIT_OBJECT_0)throw std::runtime_error("이전 앱이 아직 실행 중입니다.");}
 parentStopped=true;oldHash=fileSha256(target);installLocalBuild(root,build,&installed);localBuildStatus(root,build,"awaiting_health");auto child=updateProcess(target,L"");CloseHandle(child.hThread);childProcess=child.hProcess;DWORD healthMs=120000;wchar_t override[16];if(GetEnvironmentVariableW(L"SNUW_LOCAL_BUILD_HEALTH_MS",override,16)){auto value=std::wcstoul(override,nullptr,10);if(value>=200&&value<=120000)healthMs=value;}auto deadline=GetTickCount64()+healthMs;bool exited=false,healthy=false;auto statusFile=localBuildStatusFile(root,build);
 while(GetTickCount64()<deadline){if(localBuildState(statusFile)=="healthy"){healthy=true;break;}if(WaitForSingleObject(childProcess,200)==WAIT_OBJECT_0){exited=true;healthy=localBuildState(statusFile)=="healthy";break;}}CloseHandle(childProcess);childProcess=nullptr;
 if(healthy)return 0;if(!exited){localBuildStatus(root,build,"health_unconfirmed","앱이 실행 중이므로 강제 종료하지 않았습니다.");return 1;}throw std::runtime_error("새 빌드 시작에 실패했습니다.");
 }catch(const std::exception& error){
 bool childAlive=childProcess&&WaitForSingleObject(childProcess,0)==WAIT_TIMEOUT;if(childProcess){CloseHandle(childProcess);childProcess=nullptr;}
 localBuildLog(root,std::string("apply error: ")+error.what());
 try{if(!build.empty())localBuildStatus(root,build,childAlive?"health_unconfirmed":"failed",error.what());}catch(...){}
 if(installed&&!childAlive&&!oldHash.empty()&&oldHash!=str(build,"sha256")){try{auto backup=updatePath(root,fs::path(L".updates/local/backups")/(wide(oldHash)+L".exe"));if(!fs::exists(backup)||fileSha256(backup)!=oldHash)throw std::runtime_error("이전 빌드 백업이 없거나 손상되었습니다.");auto restore=updatePath(root,L".updates/local/restore.exe");fs::copy_file(backup,restore,fs::copy_options::overwrite_existing);if(!ReplaceFileW(target.c_str(),restore.c_str(),nullptr,0,nullptr,nullptr))throw std::runtime_error("이전 빌드 복구 실패");if(fileSha256(target)!=oldHash)throw std::runtime_error("복구 후 빌드 검증 실패");}catch(const std::exception& failure){localBuildLog(root,std::string("rollback failed: ")+failure.what());try{localBuildStatus(root,build,"rollback_failed",failure.what());}catch(...){}return 3;}}
 try{if(parentStopped&&!childAlive&&!target.empty()&&fs::exists(target)){auto child=updateProcess(target,L"");CloseHandle(child.hThread);CloseHandle(child.hProcess);}}catch(const std::exception& failure){localBuildLog(root,std::string("relaunch failed: ")+failure.what());}
 return 1;}}
}
